  return now - session.lastActivityAt >= SESSION_TIMEOUT_MS;
}

/**
 * REQ-AUTH-002: Returns the number of milliseconds remaining until the
 * existing 30-minute session timeout elapses, clamped to zero so that
 * already-expired sessions never report a negative remaining time.
 */
export function remainingSessionMs(session: Session, now: number): number {
  const elapsed = now - session.lastActivityAt;
  const remaining = SESSION_TIMEOUT_MS - elapsed;
  return remaining > 0 ? remaining : 0;
}

